-- Only disposable fixtures, all rolled back.
begin;
create function pg_temp.iv_reject(g uuid,t text,op text,p jsonb)returns void language plpgsql as $$begin begin perform public.iv_api(op,g,t,p);exception when others then return;end;raise exception 'Expected rejection: %',op;end $$;
create function pg_temp.iv_claim(g uuid,t text,x int,y int,codes text[])returns uuid language plpgsql as $$declare pid uuid:=gen_random_uuid();ids jsonb;version int;begin select jsonb_agg(q.id order by q.code)into ids from public.ng_submissions q join public.ng_teams tm on tm.id=q.team_id where q.game_id=g and tm.token=t and q.code=any(codes);select c.version into version from public.iv_cells c where c.game_id=g and c.x=iv_claim.x and c.y=iv_claim.y;perform public.iv_api('capture',g,t,jsonb_build_object('id',pid,'x',x,'y',y,'version',version,'tasks',ids));return pid;end $$;
do $$
#variable_conflict use_column
declare i int;r jsonb;s jsonb;rows jsonb;layout jsonb;g uuid;h text;ta text;tb text;a uuid;b uuid;pid uuid;first_pid uuid;spent uuid;fid uuid;stock_before int;u uuid:=gen_random_uuid();tmpl uuid;launched jsonb;begin
select jsonb_agg(jsonb_build_object('x',x,'y',y,'price',case when x=3 and y=1 then 5 else 3 end,'start',case when x=0 and y=1 then 1 when x=6 and y=1 then 2 end))into layout from generate_series(0,6)x cross join generate_series(0,2)y;
r:=public.iv_api('create',null,'',jsonb_build_object('names','["A","B"]'::jsonb,'width',7,'height',3,'counts','[6,6,1,1,1]'::jsonb,'board',layout));g:=(r->>'id')::uuid;h:=r->>'hostToken';rows:=public.ng_tasks('iv',g,h,'get')->'rows';select jsonb_agg(x||jsonb_build_object('content',public.mg_validate('{"condition":"1+0?","mode":"number","key":"1","kind":"standard","attachments":"optional"}')))into rows from jsonb_array_elements(rows)x;perform public.ng_tasks('iv',g,h,'save',jsonb_build_object('rows',rows));s:=public.iv_api('start',g,h);ta:=s->'links'->0->>'token';tb:=s->'links'->1->>'token';a:=(s->'teams'->0->>'id')::uuid;b:=(s->'teams'->1->>'id')::uuid;
assert not exists(select 1 from jsonb_array_elements(public.iv_api('state',g,ta)->'tasks')x where x->'content'?'key');assert public.iv_api('state',g,'')->'records'='[]';
r:=public.ng_files_access('upload','iv',g,ta,'{"code":"1","name":"fixture.pdf","mime":"application/pdf","size":20}');fid:=(r->>'id')::uuid;perform public.ng_files_access('ready','iv',g,ta,jsonb_build_object('id',fid));
for i in 1..15 loop perform public.iv_api('submit',g,ta,jsonb_build_object('id',gen_random_uuid(),'code',i::text,'answer','1','files',case when i=1 then jsonb_build_array(fid)else'[]'::jsonb end));perform public.iv_api('submit',g,tb,jsonb_build_object('id',gen_random_uuid(),'code',i::text,'answer','1'));end loop;
assert(select not closed from public.ng_games where id=g),'solving all tasks must not stop captures';assert jsonb_array_length(public.iv_state(g,ta)->'stocks'->a::text)=15;
perform pg_temp.iv_reject(g,ta,'capture',jsonb_build_object('id',gen_random_uuid(),'x',1,'y',0,'version',0,'tasks',jsonb_build_array((select id from public.ng_submissions where game_id=g and team_id=a and code='1'))));
first_pid:=pg_temp.iv_claim(g,ta,1,1,array['1']);perform pg_temp.iv_claim(g,ta,2,1,array['2']);perform pg_temp.iv_claim(g,tb,5,1,array['1']);perform pg_temp.iv_claim(g,tb,4,1,array['2']);
perform pg_temp.iv_reject(g,ta,'capture',jsonb_build_object('id',gen_random_uuid(),'x',3,'y',1,'version',0,'tasks',jsonb_build_array((select id from public.ng_submissions where game_id=g and team_id=a and code='3'))));
pid:=pg_temp.iv_claim(g,ta,3,1,array['7']);stock_before:=jsonb_array_length(public.iv_state(g,tb)->'stocks'->b::text);
perform pg_temp.iv_reject(g,tb,'capture',jsonb_build_object('id',gen_random_uuid(),'x',3,'y',1,'version',0,'tasks',jsonb_build_array((select id from public.ng_submissions where game_id=g and team_id=b and code='7'))));assert jsonb_array_length(public.iv_state(g,tb)->'stocks'->b::text)=stock_before,'stale conflict must not spend';
perform pg_temp.iv_reject(g,tb,'capture',jsonb_build_object('id',gen_random_uuid(),'x',3,'y',1,'version',1,'tasks',(select jsonb_agg(id)from public.ng_submissions where game_id=g and team_id=b and code in('3','13'))));
perform pg_temp.iv_claim(g,tb,3,1,array['7','8']);assert(select bid=2 and owner_id=b from public.iv_cells where game_id=g and x=3 and y=1);perform pg_temp.iv_claim(g,ta,3,1,array['8','9','10']);assert(select bid=3 and owner_id=a from public.iv_cells where game_id=g and x=3 and y=1);
-- Retry is idempotent even if the cell was subsequently recaptured.
r:=to_jsonb((select c from public.iv_captures c where id=pid));perform public.iv_api('capture',g,ta,jsonb_build_object('id',pid,'x',3,'y',1,'version',0,'tasks',r->'task_ids'));assert(select count(*)=4 from public.iv_spends z join public.iv_captures c on c.id=z.capture_id where c.game_id=g and c.x=3 and c.y=1 and c.team_id=a);
select id into spent from public.ng_submissions where game_id=g and team_id=a and code='1';perform pg_temp.iv_reject(g,h,'return',jsonb_build_object('id',spent));perform pg_temp.iv_reject(g,h,'review',jsonb_build_object('id',spent,'status','no'));
perform pg_temp.iv_reject(g,ta,'capture',jsonb_build_object('id',gen_random_uuid(),'x',0,'y',1,'version',0,'tasks','[]'::jsonb));perform pg_temp.iv_reject(g,ta,'capture',jsonb_build_object('id',gen_random_uuid(),'x',5,'y',1,'version',1,'tasks','[]'::jsonb));
-- Four-neighbor protection allows a diagonal cell beside another start.
perform pg_temp.iv_claim(g,ta,3,0,array['3']);perform pg_temp.iv_claim(g,ta,4,0,array['4']);perform pg_temp.iv_claim(g,ta,5,0,array['5']);
assert(public.ng_board(g,a)->>'total')::int=(select sum(price)from public.iv_cells where game_id=g and owner_id=a),'ranking uses cell values';
assert not has_table_privilege('anon','public.iv_cells','SELECT');assert not has_table_privilege('anon','public.iv_spends','SELECT');assert not has_table_privilege('anon','public.iv_signals','UPDATE');assert(select revision>0 from public.iv_signals where channel=public.iv_channel(g));
-- Existing scenarios retain the initial map, starts and immutable task copies.
insert into auth.users(id,email)values(u,u||'@example.invalid');perform set_config('request.jwt.claim.sub',u::text,true);r:=public.ng_templates('save',jsonb_build_object('kind','iv','game',g,'token',h,'title','Fixture'));tmpl:=(r->>'id')::uuid;launched:=public.ng_templates('launch',jsonb_build_object('id',tmpl,'request',gen_random_uuid()));assert(select count(*)=2 from public.iv_cells where game_id=(launched->>'id')::uuid and owner_id is not null);assert(select count(*)=15 from public.mg_task_copies where game_kind='iv'and game_id=(launched->>'id')::uuid);
perform public.iv_api('finish',g,h);update public.ng_lifecycle set finished_at=now()-interval '8 days'where game_id=g;perform public.ng_cleanup();assert(select count(*)=0 from public.iv_cells where game_id=g);assert(select count(*)=0 from public.iv_captures where game_id=g);assert(public.iv_state(g,'')->>'archived')::boolean;assert(select expires_at is not null from public.mg_files where id=fid);
r:=public.iv_api('create');assert(select count(*)=6 and min(price)=3 and max(price)=3 from public.iv_cells where game_id=(r->>'id')::uuid and start_team is not null);
end $$;
select 'PASS: inventory, values, captures/recaptures, protection, stale atomic conflicts, idempotency, spent-task guard, private answers/files, realtime signals, scenarios and retention' result;
rollback;
